j:jelly.g2:evaluate:
var barqCard = '';
try {
    barqCard = (function () {
        var P = 'x_2215032_ai_inc_0_ai_';
        function esc(value) {
            return String(value === null || value === undefined ? '' : value)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        }
        // In a scoped formatter the form record is not passed in; read it by its sys_id.
        var current = new GlideRecord('incident');
        var sysId = String(RP.getParameterValue('sys_id') || '');
        var isNew = !sysId || sysId == '-1' || !current.get(sysId);
        function val(name) { return String(current.getValue(name) || ''); }
        if (isNew)
            return '<div class="barq-card barq-muted"><div class="barq-head"><span class="barq-logo">BARQ AI</span>' +
                '<span class="barq-chip">Tick AI Enabled and save: BARQ AI Agent starts on this incident</span></div></div>';

        var agentUser = gs.getProperty('x_2215032_ai_inc_0.agent_user_name', 'ai_orchestrator_svc');
        var aiState = val(P + 'processing_state');
        var locked = val(P + 'human_lock') == '1';
        var enabled = val(P + 'enabled') == '1';
        var state = val('state');
        var waitingCaller = state == '3' && val('hold_reason') == '1';
        var resolvedByAgent = String(current.resolved_by.user_name) == agentUser;
        var confidence = parseFloat(val(P + 'confidence'));
        var fix = val(P + 'resolution') || val(P + 'suggestion');
        var failure = val(P + 'failure_reason');

        var status, tone, owner, hint = '';
        if (!enabled) {
            status = 'AI is off for this incident'; tone = 'muted'; owner = 'Engineers';
            hint = 'Tick AI Enabled and save to let BARQ AI Agent work on it.';
        } else if (locked) {
            status = 'An engineer has taken over'; tone = 'muted'; owner = 'Engineer';
            hint = 'BARQ AI Agent will not write to this incident. Use Hand back to BARQ AI to return it, with an instruction in Work notes.';
        } else if (aiState == 'pending') {
            status = 'Queued for BARQ AI'; tone = 'info'; owner = 'BARQ AI Agent';
        } else if (aiState == 'in_progress' && waitingCaller) {
            status = 'Waiting for the caller to answer a question'; tone = 'info'; owner = 'BARQ AI Agent';
            hint = 'The caller\'s answer brings it back to the agent automatically.';
        } else if (aiState == 'in_progress') {
            status = 'BARQ AI is working on it'; tone = 'info'; owner = 'BARQ AI Agent';
        } else if (aiState == 'awaiting_approval') {
            status = 'Waiting for an engineer to approve'; tone = 'warn'; owner = 'Waiting for approval';
            hint = 'Review the fix, then Approve AI fix or Reject AI fix. To send your own fix, edit AI Resolution first.';
        } else if (aiState == 'failed') {
            status = 'BARQ AI could not finish'; tone = 'bad'; owner = 'Engineers';
            hint = 'Handle it yourself, or Hand back to BARQ AI with an instruction.';
        } else if (aiState == 'complete' && resolvedByAgent && state == '7') {
            status = 'Resolved by BARQ AI and closed'; tone = 'good'; owner = 'Closed';
        } else if (aiState == 'complete' && resolvedByAgent && state == '6') {
            status = 'Resolved by BARQ AI, waiting for the caller'; tone = 'good'; owner = 'Caller';
            hint = 'If the caller replies or reopens it, it comes back to an engineer with this fix.';
        } else if (aiState == 'complete') {
            status = 'Fix ready for the engineer'; tone = 'info'; owner = 'Engineers';
            hint = 'BARQ AI Agent routed and started this incident; the fix below needs an engineer.';
        } else {
            status = 'Not processed by BARQ AI'; tone = 'muted'; owner = 'Engineers';
        }

        var html = [];
        html.push('<div class="barq-card barq-' + tone + '">');
        html.push('<div class="barq-head"><span class="barq-logo">BARQ AI</span>');
        html.push('<span class="barq-chip">' + esc(status) + '</span>');
        html.push('<span class="barq-owner">In control: <b>' + esc(owner) + '</b></span></div>');

        var facts = [];
        var type = current.getDisplayValue(P + 'classification');
        if (type) facts.push('Type: <b>' + esc(type) + '</b>');
        if (!isNaN(confidence)) {
            var pct = Math.round(confidence * 100);
            facts.push('Confidence: <b>' + pct + '%</b> <span class="barq-bar"><span style="width:' + pct + '%"></span></span>');
        }
        var updated = current.getDisplayValue(P + 'processing_end');
        if (updated) facts.push('Updated: ' + esc(updated));
        if (facts.length) html.push('<div class="barq-facts"><span>' + facts.join('</span><span class="barq-sep"></span><span>') + '</span></div>');
        if (hint) html.push('<div class="barq-hint">' + esc(hint) + '</div>');
        if (aiState == 'failed' && failure) html.push('<div class="barq-failure">' + esc(failure) + '</div>');

        if (fix) {
            var lines = fix.split(/\r?\n/), steps = [], sources = [];
            for (var i = 0; i < lines.length; i++) {
                var line = lines[i].replace(/^\s+|\s+$/g, '');
                if (!line) continue;
                if (/^Sources?:/i.test(line)) { sources.push(line.replace(/^Sources?:\s*/i, '')); continue; }
                steps.push(line.replace(/^\d+[.)]\s*/, ''));
            }
            html.push('<div class="barq-fix-title">' + (aiState == 'awaiting_approval' ? 'Proposed fix' : 'Fix') + '</div><ol class="barq-steps">');
            for (var s = 0; s < steps.length && s < 12; s++)
                html.push('<li>' + esc(steps[s]).replace(/\[(KB\d{4,7}[^\]]*)\]/g, '<span class="barq-kb">$1</span>') + '</li>');
            html.push('</ol>');
            if (sources.length) html.push('<div class="barq-sources">Sources: ' + esc(sources.join('; ')) + '</div>');
        }
        html.push('</div>');
        return html.join('');
    })();
} catch (e) {
    barqCard = '<div class="barq-card barq-muted">BARQ AI card unavailable.</div>';
    gs.warn('BARQ AI card error: ' + e);
}
barqCard;
